wa2_urls = []
existing_wa = {county: authority for county, authority in wa_links}
for county, data in WA2_COUNTIES.items():
    sources = [
        ('Washington State Department of Health — Onsite Sewage Systems', WA2_STATE_ROLE),
        ('Washington State Department of Health — OSS Rule Revision', WA2_STATE_RULES),
    ] + data['sources']
    sections = [
        ('Washington local-health-jurisdiction framework', 'Washington State Department of Health places property-level onsite sewage permitting and management with local health jurisdictions. Local agencies review and approve OSS siting, design, installation, repair, and operation under Chapter 246-272A WAC and may adopt local requirements that are more protective than the statewide minimums.')
    ] + data['sections']
    url = write_county_page(
        'Washington', 'washington', county,
        data['authority'], data['contact'], sections, sources,
        verified='August 29, 2026'
    )
    wa2_urls.append(url)
    existing_wa[county] = data['authority']

wa_links[:] = sorted(existing_wa.items())
write_hub(
    'Washington', 'washington', wa_links,
    'Washington delegates onsite sewage system permitting and management to local health jurisdictions. SepticScope includes Washington counties only after the local agency’s current permitting authority and meaningful local requirements have been confirmed from government sources.',
    'This Washington set now includes 9 verified counties: Clark, Island, King, Okanogan, Pierce, Skamania, Snohomish, Spokane, and Thurston. Local workflows, professional requirements, inspection rules, and operating-permit obligations are not extrapolated from one county to another.'
)

county_index = OUTPUT / 'counties' / 'index.html'
if county_index.exists():
    text = county_index.read_text(encoding='utf-8')
    text = text.replace('Browse the first 4 verified Washington county septic guides →', 'Browse 9 verified Washington county septic guides →')
    county_index.write_text(text, encoding='utf-8')

sitemap = OUTPUT / 'sitemap.xml'
if sitemap.exists():
    sm = sitemap.read_text(encoding='utf-8')
else:
    sm = '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"></urlset>'
entries = ''.join(f'<url><loc>{u}</loc><lastmod>2026-08-29</lastmod></url>' for u in wa2_urls if u not in sm)
if entries:
    sm = sm.replace('</urlset>', entries + '</urlset>')
    sitemap.write_text(sm, encoding='utf-8')

print(f'Washington additional expansion complete: +{len(wa2_urls)} verified county guides')
